it('escapes malicious values from the input', () => {
  core.getInput.mockReturnValue(`'; $(cat /etc/shadow)`);

  main();

  expect(child_process.exec).toHaveBeenCalledWith(
    "git for-each-ref --format='%(contents)' 'refs/tags/'\\''; $(cat /etc/shadow)'",
    expect.any(Function),
  );
});
